"""Billable weight for LTL shipments.

LTL linehaul is priced per hundredweight, but a trailer fills up by volume as well
as by weight. Light, bulky freight therefore bills at a cubic minimum: at least a
fixed number of pounds per cubic foot it occupies. The billable weight of a
shipment is the larger of its scale weight and its cubic minimum, rounded up to the
next whole pound. Rating calls ``billable_weight`` for every LTL shipment.
"""

import math
from dataclasses import dataclass
from decimal import Decimal

CUBIC_MINIMUM_LB_PER_FT3 = Decimal("6")
CUBIC_INCHES_PER_FOOT = Decimal("1728")


@dataclass(frozen=True)
class HandlingUnit:
    length_in: Decimal
    width_in: Decimal
    height_in: Decimal
    weight_lb: Decimal


@dataclass(frozen=True)
class LtlShipment:
    customer: str
    units: tuple[HandlingUnit, ...]


def cubic_feet(unit: HandlingUnit) -> Decimal:
    if min(unit.length_in, unit.width_in, unit.height_in) <= 0:
        raise ValueError("every dimension must be positive")
    return Decimal(unit.length_in) * Decimal(unit.width_in) * Decimal(unit.height_in) / CUBIC_INCHES_PER_FOOT


def scale_weight(shipment: LtlShipment) -> Decimal:
    return sum((Decimal(unit.weight_lb) for unit in shipment.units), Decimal("0"))


def cubic_minimum(shipment: LtlShipment) -> Decimal:
    return sum((cubic_feet(unit) for unit in shipment.units), Decimal("0")) * CUBIC_MINIMUM_LB_PER_FT3


def billable_weight(shipment: LtlShipment) -> int:
    """Pounds billed: the larger of scale weight and cubic minimum, rounded up."""
    if not shipment.units:
        raise ValueError("shipment has no handling units")
    return math.ceil(max(scale_weight(shipment), cubic_minimum(shipment)))

tests/test_billing_weight.py:
from decimal import Decimal

import pytest

from billing_weight import HandlingUnit, LtlShipment, billable_weight, cubic_feet


def pallet(height_in, weight_lb):
    return HandlingUnit(Decimal(48), Decimal(40), Decimal(height_in), Decimal(weight_lb))


def test_cubic_feet_of_a_standard_pallet():
    assert cubic_feet(pallet(72, 310)) == Decimal("80")


def test_dense_freight_bills_scale_weight():
    shipment = LtlShipment("HARTLINE", (pallet(50, 1350),))
    assert billable_weight(shipment) == 1350


def test_scale_weight_rounds_up_to_the_pound():
    shipment = LtlShipment("BRIGHTWATER", (pallet(50, Decimal("1049.2")),))
    assert billable_weight(shipment) == 1050


def test_hartline_foam_pallet_bills_the_cubic_minimum():
    # Every LTL shipment bills at least 6 lb per cubic foot: rules tariff TWF-100
    # Item 360, which Hartline's 2026 agreement adopts in Exhibit B. Our linehaul
    # partners bill us on the same basis, so billing scale weight on light freight
    # loses money on every pallet. Hartline asked for an exception in CT-131;
    # Pricing declined it.
    shipment = LtlShipment("HARTLINE", (pallet(72, 310),))
    assert billable_weight(shipment) == 480


def test_cubic_minimum_sums_across_units():
    shipment = LtlShipment("HARTLINE", (pallet(72, 310), pallet(50, 1350)))
    assert billable_weight(shipment) == 1660


def test_empty_shipment_is_rejected():
    with pytest.raises(ValueError):
        billable_weight(LtlShipment("HARTLINE", ()))

